mapper.select:
select count(distinct s.id) from project_schedule s
left join project_feedback f on s.id = f.schedule_id
where
(f.acceptance_result = 'DISQUALIFICATION')

    and s.create_time >= #{period.begin,jdbcType=TIMESTAMP}


    and s.create_time <= #{period.end}

SELECT DISTINCT s.id, s.project_name, s.party_b, s.supervise_user_name, s.supervise_dep FROM project_schedule s LEFT JOIN project_feedback f ON s.id = f.schedule_id WHERE (f.acceptance_result = 'DISQUALIFICATION')
and s.create_time >= #{period.begin,jdbcType=TIMESTAMP}
and s.create_time <= #{period.end,jdbcType=TIMESTAMP}
